// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account) public {
        // Ensure account is not the zero address to avoid issues with some ERC20 implementations
        vm.assume(account != address(0));

        // Before any staking, balanceOf should return 0
        assertTrue(c.balanceOf(account) == 0);

        // Add a reward token (required for some internal logic, but doesn't affect balance)
        c.addReward(address(this));

        // After adding reward token, balanceOf should still return 0
        assertTrue(c.balanceOf(account) == 0);
    }
}

